import time, socket; from contextlib import suppress
from selenium import webdriver; from selenium.webdriver.common.by import By; from db import query
B = "http://127.0.0.1:5000"; E = f"t{int(time.time())}@test.com"; A = "a" + E; R = []; up = socket.socket().connect_ex(("127.0.0.1", 5000)) == 0
if not up: raise SystemExit("\nERROR: SafeRoute is NOT running. Open a new terminal, run 'python app.py', then run this test again.")
d = webdriver.Chrome(); d.maximize_window(); go = lambda p: (d.get(B + p), time.sleep(1)); fill = lambda **k: [d.find_element(By.NAME, n).send_keys(v) for n, v in k.items()]; send = lambda x="//main//button[@type='submit']": (d.find_element(By.XPATH, x).click(), time.sleep(1.5)); has = lambda s: s in d.execute_script("return (document.body || {}).textContent || ''")
with suppress(Exception): d.execute_cdp_cmd("Browser.grantPermissions", {"origin": B, "permissions": ["geolocation"]}); d.execute_cdp_cmd("Emulation.setGeolocationOverride", {"latitude": 20.59, "longitude": 78.96, "accuracy": 50})
reg = lambda e, p="secret123": (go("/register"), fill(name="Tester", email=e, password=p), send()); log = lambda e, p="secret123": (go("/login"), fill(email=e, password=p), send()); wait = lambda f, s=20: next((True for _ in range(s) if (time.sleep(1) or f())), False)
T = [("TC01", "Register (valid)", lambda: (reg(E), has("Account created"))[-1]), ("TC02", "Register (duplicate)", lambda: (reg(E), has("already registered"))[-1]), ("TC03", "Register (short password)", lambda: (reg("s" + E, "123"), "/register" in d.current_url and not has("Account created"))[-1]),
     ("TC04", "Login (valid)", lambda: (log(E), "/dashboard" in d.current_url)[-1]), ("TC05", "Login (invalid)", lambda: (d.delete_all_cookies(), log(E, "wrong123"), has("Invalid email or password"))[-1]), ("TC06", "Logout", lambda: (log(E), go("/logout"), has("logged out"))[-1]),
     ("TC07", "Home page statistics", lambda: (go("/"), has("Safe places") and has("Community members"))[-1]), ("TC08", "Dashboard (not logged in)", lambda: (go("/dashboard"), "/login" in d.current_url and has("Please log in first"))[-1]),
     ("TC09", "Route planning", lambda: (log(E), go("/dashboard"), d.find_element(By.ID, "start").send_keys("Delhi"), d.find_element(By.ID, "end").send_keys("Agra"), d.find_element(By.ID, "findBtn").click(), wait(lambda: d.find_elements(By.CSS_SELECTOR, ".route")) and has("Safest"))[-1]),
     ("TC10", "Map layers", lambda: (go("/dashboard"), (b := d.find_element(By.ID, "layerSafe")).click(), (off := not b.is_selected()), b.click(), off and b.is_selected())[-1]), ("TC11", "SOS record", lambda: (go("/dashboard"), d.execute_script("setTimeout(() => document.getElementById('sosBtn').click(), 100)"), time.sleep(1), d.switch_to.alert.accept(), wait(lambda: d.find_elements(By.CSS_SELECTOR, ".sos-box")))[-1]),
     ("TC12", "Report incident", lambda: (go("/report"), d.find_element(By.ID, "location").send_keys("Test spot"), d.find_element(By.ID, "description").send_keys("Test incident"), d.find_element(By.ID, "reportMap").click(), d.find_element(By.CSS_SELECTOR, "#incidentForm button[type='submit']").click(), wait(lambda: has("Test spot")))[-1]),
     ("TC13", "Add emergency contact", lambda: (go("/safety"), fill(name="Test Contact", phone="9876543210", relationship="Friend"), send("//button[normalize-space()='Add']"), has("Contact added") and has("Test Contact"))[-1]), ("TC14", "Feedback", lambda: (go("/feedback"), send(), (n := has("Please choose a star rating")), go("/feedback"), d.find_element(By.CSS_SELECTOR, "label[for='s5']").click(), fill(comments="Good app"), send(), n and has("Thank you for your feedback"))[-1]),
          ("TC15", "Admin access", lambda: (go("/admin"), (n := has("Admins only")), reg(A), query("UPDATE users SET is_admin=1 WHERE email=%s", (A,), commit=True), d.delete_all_cookies(), log(A), go("/admin"), n and has("Admin panel"))[-1]), ("TC16", "Phone validation (bug check)", lambda: (go("/safety"), fill(name="Bad Phone", phone="abc"), send("//button[normalize-space()='Add']"), not has("Contact added"))[-1]), ("TC17", "Password validation (bug check)", lambda: (d.delete_all_cookies(), reg("p" + E, " " * 6), not has("Account created"))[-1])]
for tc, name, f in T:
    ok = False
    with suppress(Exception): ok = bool(f())
    R.append(ok); print(f"{tc}  {name:<28}{'PASS' if ok else 'FAIL'}")
print(f"\nTotal: {len(R)}   Passed: {sum(R)}   Failed: {len(R) - sum(R)}"); d.quit()